const EXPECTED = $("Workflow Config").first().json.Sender.toLowerCase();
const MAX_BODY = 6000;
const now = new Date();
const from = new Date(now.getTime() - 7 * 24 * 3600 * 1000);
const emails = [];

for (const item of $input.all()) {
  const m = item.json;
  if (!m || !m.id) continue;

  const addr = (m.from && m.from.emailAddress && m.from.emailAddress.address) || (m.sender && m.sender.emailAddress && m.sender.emailAddress.address) || '';
  if (addr.toLowerCase() !== EXPECTED) continue;

  const received = m.receivedDateTime ? new Date(m.receivedDateTime) : null;
  if (received && received < from) continue;

  let body = (m.body && m.body.content) || m.bodyPreview || '';
  body = body
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/\s+/g, ' ')
    .trim();
  if (body.length > MAX_BODY) body = body.slice(0, MAX_BODY) + ' [truncated]';

  emails.push({
    id: m.id,
    subject: m.subject || '',
    received: m.receivedDateTime || '',
    hasAttachments: !!m.hasAttachments,
    body: body
  });
}

return [{ json: {
  count: emails.length,
  periodFrom: from.toISOString().slice(0, 10),
  periodTo: now.toISOString().slice(0, 10),
  emails: emails
} }];

