const r = $input.first().json.output || {};

const esc = (v) => {
  const s = (v === undefined || v === null || v === '') ? 'Not specified' : String(v);
  return s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');
};

const TD = 'style="border:1px solid #ddd;padding:6px 8px;vertical-align:top;"';
const TH = 'style="border:1px solid #ddd;padding:6px 8px;background:#1f3a5f;color:#fff;text-align:left;"';
const TABLE = 'style="border-collapse:collapse;width:100%;font-size:13px;margin-bottom:16px;"';

const list = (arr) => (Array.isArray(arr) && arr.length)
  ? '<ul>' + arr.map((x) => '<li>' + esc(x) + '</li>').join('') + '</ul>'
  : '<p>None</p>';

const counts = (title, obj) => {
  const rows = Object.entries(obj || {}).map(([k, v]) => '<tr><td ' + TD + '>' + esc(k) + '</td><td ' + TD + '>' + esc(v) + '</td></tr>').join('');
  return '<h3>' + title + '</h3><table ' + TABLE + '><tr><th ' + TH + '>Category</th><th ' + TH + '>Count</th></tr>' + rows + '</table>';
};

const incidents = Array.isArray(r.incidents) ? r.incidents : [];
const incidentRows = incidents.map((i) =>
  '<tr>' +
  ['date', 'type', 'severity', 'location', 'injuries', 'root_cause', 'corrective_actions', 'status']
    .map((k) => '<td ' + TD + '>' + esc(i[k]) + '</td>').join('') +
  '</tr>'
).join('');

const risks = Array.isArray(r.risk_alerts) ? r.risk_alerts : [];
const riskBox = risks.length
  ? '<div style="background:#fdecea;border-left:5px solid #c62828;padding:10px 14px;margin:14px 0;"><h3 style="margin:0 0 6px 0;color:#c62828;">Risk Alerts</h3>' + list(risks) + '</div>'
  : '';

const html =
  '<div style="font-family:Arial,sans-serif;color:#222;max-width:900px;">' +
  '<h2>Incident Analysis</h2>' +
  '<p><b>Period:</b> ' + esc(r.period) + '<br><b>Total incidents:</b> ' + esc(r.total_incidents) + '</p>' +
  riskBox +
  '<h3>All Incidents</h3>' +
  '<table ' + TABLE + '><tr>' +
  ['Date', 'Type', 'Severity', 'Location', 'Injuries', 'Root cause', 'Corrective actions', 'Status'].map((h) => '<th ' + TH + '>' + h + '</th>').join('') +
  '</tr>' + incidentRows + '</table>' +
  counts('By Severity', r.by_severity) +
  counts('By Type', r.by_type) +
  counts('By Location', r.by_location) +
  '<h3>Trends and Patterns</h3><p>' + esc(r.trends_and_patterns) + '</p>' +
  '<h3>Recommendations</h3>' + list(r.recommendations) +
  '</div>';

return [{ json: { html: html } }];
